  7	import br.com.marealta.repository.MessageRepository;
  8	import br.com.marealta.repository.ReservationRepository;
  9	import br.com.marealta.repository.RoomRepository;
 10	import br.com.marealta.service.*;
 11	import com.fasterxml.jackson.databind.DeserializationFeature;
 12	import com.fasterxml.jackson.databind.ObjectMapper;
 13	import com.fasterxml.jackson.databind.SerializationFeature;
 14	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 15	import com.zaxxer.hikari.HikariConfig;
 16	import com.zaxxer.hikari.HikariDataSource;
 17	import io.javalin.Javalin;
 18	import io.javalin.http.HttpStatus;
 19	import io.javalin.json.JavalinJackson;
 20	
 21	import javax.sql.DataSource;
 22	
 23	public class Application {
 24	
 25	    public static void main(String[] args) {
 26	        DataSource dataSource = createDataSource();
 27	
 28	        DatabaseInitializer.initialize(dataSource);
 29	
 30	        RoomRepository roomRepository = new RoomRepository(dataSource);
 31	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 32	        MessageRepository messageRepository = new MessageRepository(dataSource);
 33	
 34	        roomRepository.initializeRooms();
 35	
 36	        PricingService pricingService = new PricingService();
 37	        DocumentService documentService = new DocumentService(pricingService);
 38	        EmailService emailService = new EmailService(messageRepository);
 39	        ReservationService reservationService = new ReservationService(
 40	            reservationRepository,
 41	            roomRepository,
 42	            pricingService,
 43	            documentService,
 44	            emailService
 45	        );
 46	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 47	
 48	        RoomController roomController = new RoomController(roomRepository);
 49	        ReservationController reservationController = new ReservationController(
 50	            reservationService,
 51	            roomRepository,
 52	            documentService
 53	        );
 54	        MessageController messageController = new MessageController(messageRepository);
 55	        ReportController reportController = new ReportController(reportService);
 56	
 57	        int port = getPort();
 58	
 59	        Javalin app = Javalin.create(config -> {
 60	            ObjectMapper objectMapper = new ObjectMapper();
 61	            objectMapper.registerModule(new JavaTimeModule());
 62	            objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 63	            objectMapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
 64	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 65	        });
 66	
 67	        app.get("/rooms", roomController::getRooms);
 68	        app.post("/reservations", reservationController::createReservation);
 69	        app.get("/reservations/{id}", reservationController::getReservation);
 70	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 71	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 72	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 73	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 74	        app.get("/reservations/{id}/document", reservationController::getDocument);
 75	        app.get("/messages", messageController::getMessages);
 76	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 77	        app.get("/reports/revenue", reportController::getRevenueReport);
 78	
 79	        app.exception(PousadaException.class, (e, ctx) -> {
 80	            ctx.status(e.getHttpStatus())
 81	               .json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
 82	        });
 83	
 84	        app.exception(Exception.class, (e, ctx) -> {
 85	            e.printStackTrace();
 86	            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR)
 87	               .json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
 88	        });
 89	
 90	        app.start(port);
 91	
 92	        System.out.println("Pousada Maré Alta system running on port " + port);
 93	    }
 94	
 95	    private static DataSource createDataSource() {
 96	        String dbUrl = System.getenv("DB_URL");
 97	        String dbUser = System.getenv("DB_USER");
 98	        String dbPassword = System.getenv("DB_PASSWORD");
 99	
100	        if (dbUrl == null || dbUser == null || dbPassword == null) {
101	            throw new RuntimeException("Database configuration not found. Set DB_URL, DB_USER, and DB_PASSWORD environment variables.");
102	        }
103	
104	        HikariConfig config = new HikariConfig();
105	        config.setJdbcUrl(dbUrl);
106	        config.setUsername(dbUser);
107	        config.setPassword(dbPassword);
108	        config.setMaximumPoolSize(10);
109	
110	        return new HikariDataSource(config);
111	    }
112	
113	    private static int getPort() {
114	        String portEnv = System.getenv("PORT");
115	        if (portEnv != null && !portEnv.isBlank()) {
116	            try {
117	                return Integer.parseInt(portEnv);
118	            } catch (NumberFormatException e) {
119	                System.err.println("Invalid PORT value: " + portEnv + ". Using default 7070");
120	            }
121	        }
122	        return 7070;
123	    }
124	}
