163	
164	    public void getOccupancyReport(Context ctx) {
165	        String dateParam = ctx.queryParam("date");
166	
167	        if (dateParam == null || dateParam.isBlank()) {
168	            throw new InvalidRequestException("Missing required parameter: date");
169	        }
170	
171	        LocalDate date;
172	        try {
173	            date = LocalDate.parse(dateParam);
174	        } catch (DateTimeParseException e) {
175	            throw new InvalidRequestException("Invalid date format: " + dateParam);
176	        }
177	
178	        String csv = reportService.generateOccupancyReport(date);
179	        ctx.contentType("text/csv; charset=utf-8").result(csv);
180	    }
