229	        this.documentService = documentService;
230	    }
231	
232	    public void createReservation(Context ctx) {
233	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
234	
235	        validateRequest(request);
236	
237	        GuestIdentification guestId = parseGuestIdentification(request);
238	        LocalDate checkIn = parseDate(request.checkIn(), "checkIn");
239	        LocalDate checkOut = parseDate(request.checkOut(), "checkOut");
240	        RatePlan ratePlan = parseRatePlan(request.ratePlan());
241	
242	        if (request.guests() == null) {
243	            throw new InvalidRequestException("Missing required field: guests");
244	        }
245	
246	        Reservation reservation = reservationService.createReservation(
247	            request.roomNumber(),
248	            request.guestName(),
249	            request.guestEmail(),
250	            guestId,
251	            checkIn,
252	            checkOut,
253	            request.guests(),
254	            ratePlan
255	        );
256	
257	        ctx.status(201).json(ReservationDTO.from(reservation));
258	    }
