272	    public void cancelReservation(Context ctx) {
273	        Long id = parseLongParam(ctx.pathParam("id"));
274	        Reservation reservation = reservationService.cancelReservation(id);
275	        ctx.json(ReservationDTO.from(reservation));
276	    }
