284	    public void checkOut(Context ctx) {
285	        Long id = parseLongParam(ctx.pathParam("id"));
286	        Reservation reservation = reservationService.checkOut(id);
287	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
288	        String documentText = documentService.generateDocument(reservation, room);
289	        ctx.json(DocumentDTO.from(reservation, room, documentText));
290	    }
291	
292	    public void getDocument(Context ctx) {
293	        Long id = parseLongParam(ctx.pathParam("id"));
294	        Reservation reservation = reservationService.getReservation(id);
295	
296	        if (reservation.getAmountPaid().doubleValue() == 0) {
297	            throw new InvalidRequestException("Document only available for paid reservations");
298	        }
299	
300	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
301	        String documentText = documentService.generateDocument(reservation, room);
302	        ctx.json(DocumentDTO.from(reservation, room, documentText));
303	    }
304	
305	    private void validateRequest(CreateReservationRequest request) {
306	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
307	            throw new InvalidRequestException("Missing required field: roomNumber");
308	        }
309	        if (request.guestName() == null || request.guestName().isBlank()) {
310	            throw new InvalidRequestException("Missing required field: guestName");
311	        }
312	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
313	            throw new InvalidRequestException("Missing required field: guestEmail");
314	        }
315	        if (request.checkIn() == null || request.checkIn().isBlank()) {
316	            throw new InvalidRequestException("Missing required field: checkIn");
317	        }
318	        if (request.checkOut() == null || request.checkOut().isBlank()) {
319	            throw new InvalidRequestException("Missing required field: checkOut");
320	        }
321	        if (request.ratePlan() == null || request.ratePlan().isBlank()) {
322	            throw new InvalidRequestException("Missing required field: ratePlan");
323	        }
324	    }
325	
326	    private GuestIdentification parseGuestIdentification(CreateReservationRequest request) {
327	        boolean hasCpf = request.guestCpf() != null && !request.guestCpf().isBlank();
328	        boolean hasCnpj = request.companyCnpj() != null && !request.companyCnpj().isBlank();
329	        boolean hasPassport = request.guestPassport() != null && !request.guestPassport().isBlank();
330	
331	        int identificationCount = (hasCpf ? 1 : 0) + (hasCnpj ? 1 : 0) + (hasPassport ? 1 : 0);
332	
333	        if (identificationCount != 1) {
334	            throw new InvalidRequestException(
335	                "Must provide exactly one identification type: guestCpf, or companyCnpj+companyName, or guestPassport+guestCountry"
336	            );
337	        }
338	
339	        if (hasCpf) {
340	            return new GuestIdentification.IndividualGuest(request.guestCpf());
341	        }
342	
343	        if (hasCnpj) {
344	            if (request.companyName() == null || request.companyName().isBlank()) {
345	                throw new InvalidRequestException("companyName is required when companyCnpj is provided");
346	            }
347	            return new GuestIdentification.CorporateGuest(request.companyCnpj(), request.companyName());
348	        }
349	
350	        if (hasPassport) {
351	            if (request.guestCountry() == null || request.guestCountry().isBlank()) {
352	                throw new InvalidRequestException("guestCountry is required when guestPassport is provided");
353	            }
354	            return new GuestIdentification.ForeignGuest(request.guestPassport(), request.guestCountry());
355	        }
356	
357	        throw new InvalidRequestException("No valid guest identification provided");
358	    }
359	
360	    private LocalDate parseDate(String date, String fieldName) {
361	        try {
362	            return LocalDate.parse(date);
363	        } catch (DateTimeParseException e) {
364	            throw new InvalidRequestException("Invalid date format for " + fieldName + ": " + date);
365	        }
366	    }
367	
368	    private RatePlan parseRatePlan(String ratePlan) {
369	        try {
370	            return RatePlan.valueOf(ratePlan);
371	        } catch (IllegalArgumentException e) {
372	            throw new InvalidRequestException("Invalid rate plan: " + ratePlan);
373	        }
374	    }
375	
376	    private Long parseLongParam(String param) {
377	        try {
378	            return Long.parseLong(param);
379	        } catch (NumberFormatException e) {
380	            throw new InvalidRequestException("Invalid ID: " + param);
381	        }
382	    }
383	}
