 14	public class DocumentService {
 15	    private final PricingService pricingService;
 16	    private static final DateTimeFormatter BR_DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 17	    private static final DateTimeFormatter ISO_DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE;
 18	
 19	    public DocumentService(PricingService pricingService) {
 20	        this.pricingService = pricingService;
 21	    }
