 23	    public String generateDocument(Reservation reservation, Room room) {
 24	        return switch (reservation.getGuestIdentification()) {
 25	            case GuestIdentification.IndividualGuest ig -> generateComprovante(reservation, room);
 26	            case GuestIdentification.CorporateGuest cg -> generateFatura(reservation, room, cg);
 27	            case GuestIdentification.ForeignGuest fg -> generateBookingReceipt(reservation, room, fg);
 28	        };
