 30	
 31	    private String generateComprovante(Reservation reservation, Room room) {
 32	        StringBuilder sb = new StringBuilder();
 33	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
 34	        sb.append("Hóspede: ").append(reservation.getGuestName());
 35	
 36	        if (reservation.getGuestIdentification() instanceof GuestIdentification.IndividualGuest ig) {
 37	            sb.append(" (CPF ").append(formatCpf(ig.cpf())).append(")");
 38	        }
 39	
 40	        sb.append("\n");
 41	        sb.append("Quarto: ").append(reservation.getRoomNumber());
 42	        sb.append(" (").append(room.getType()).append(")\n");
 43	        sb.append("Entrada: ").append(reservation.getCheckIn().format(BR_DATE_FORMAT));
 44	        sb.append(" | Saída: ").append(reservation.getCheckOut().format(BR_DATE_FORMAT));
 45	        sb.append(" | ").append(reservation.getNights());
 46	        sb.append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
 47	        sb.append("Diárias: ").append(formatBRL(reservation.getSubtotal())).append("\n");
 48	
 49	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 50	            sb.append("Desconto: ").append(formatBRL(reservation.getDiscount())).append("\n");
 51	        }
 52	
 53	        sb.append("Total: ").append(formatBRL(reservation.getTotal()));
 54	
 55	        return sb.toString();
 56	    }
 57	
 58	    private String generateFatura(Reservation reservation, Room room, GuestIdentification.CorporateGuest corporate) {
 59	        StringBuilder sb = new StringBuilder();
 60	        sb.append("Fatura de hospedagem nº ").append(reservation.getId()).append("\n");
 61	        sb.append("Empresa: ").append(corporate.companyName());
 62	        sb.append(" (CNPJ ").append(formatCnpj(corporate.cnpj())).append(")\n");
 63	        sb.append("Hóspede: ").append(reservation.getGuestName()).append("\n");
 64	        sb.append("Quarto: ").append(reservation.getRoomNumber());
 65	        sb.append(" (").append(room.getType()).append(")\n");
 66	        sb.append("Entrada: ").append(reservation.getCheckIn().format(BR_DATE_FORMAT));
 67	        sb.append(" | Saída: ").append(reservation.getCheckOut().format(BR_DATE_FORMAT));
 68	        sb.append(" | ").append(reservation.getNights());
 69	        sb.append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
 70	        sb.append("Diárias: ").append(formatBRL(reservation.getSubtotal())).append("\n");
 71	
 72	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 73	            sb.append("Desconto: ").append(formatBRL(reservation.getDiscount())).append("\n");
 74	        }
 75	
 76	        sb.append("Total: ").append(formatBRL(reservation.getTotal())).append("\n");
 77	
 78	        BigDecimal iss = pricingService.calculateIss(reservation.getTotal());
 79	        sb.append("ISS retido (5%): ").append(formatBRL(iss));
 80	
 81	        return sb.toString();
 82	    }
 83	
 84	    private String generateBookingReceipt(Reservation reservation, Room room, GuestIdentification.ForeignGuest foreign) {
 85	        StringBuilder sb = new StringBuilder();
 86	        sb.append("Booking receipt no. ").append(reservation.getId()).append("\n");
 87	        sb.append("Guest: ").append(reservation.getGuestName());
 88	        sb.append(" (passport ").append(foreign.passport());
 89	        sb.append(", ").append(foreign.country()).append(")\n");
 90	        sb.append("Room: ").append(reservation.getRoomNumber());
 91	        sb.append(" (").append(room.getType()).append(")\n");
 92	        sb.append("Check-in: ").append(reservation.getCheckIn().format(ISO_DATE_FORMAT));
 93	        sb.append(" | Check-out: ").append(reservation.getCheckOut().format(ISO_DATE_FORMAT));
 94	        sb.append(" | ").append(reservation.getNights());
 95	        sb.append(reservation.getNights() == 1 ? " night" : " nights").append("\n");
 96	        sb.append("Nights: ").append(formatUSD(reservation.getSubtotal())).append("\n");
 97	
 98	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 99	            sb.append("Discount: ").append(formatUSD(reservation.getDiscount())).append("\n");
100	        }
101	
102	        sb.append("Total: ").append(formatUSD(reservation.getTotal()));
103	
104	        return sb.toString();
105	    }
106	
107	    private String formatBRL(BigDecimal value) {
108	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
109	        symbols.setGroupingSeparator('.');
110	        symbols.setDecimalSeparator(',');
111	        DecimalFormat df = new DecimalFormat("#,##0.00", symbols);
112	        return "R$ " + df.format(value);
113	    }
114	
115	    private String formatUSD(BigDecimal value) {
116	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
117	        symbols.setGroupingSeparator(',');
118	        symbols.setDecimalSeparator('.');
119	        DecimalFormat df = new DecimalFormat("#,##0.00", symbols);
120	        return "BRL " + df.format(value);
121	    }
122	
123	    private String formatCpf(String cpf) {
124	        if (cpf.length() == 11) {
125	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
126	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
127	        }
128	        return cpf;
129	    }
130	
131	    private String formatCnpj(String cnpj) {
132	        if (cnpj.length() == 14) {
133	            return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
134	                   cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" +
135	                   cnpj.substring(12);
136	        }
137	        return cnpj;
138	    }
139	}
