279	    }
280	
281	    public String generateRevenueReport(int year, int month) {
282	        List<Reservation> reservations = reservationRepository.findByMonth(year, month);
283	
284	        StringBuilder csv = new StringBuilder();
285	        csv.append("reservation,room,check_in,check_out,status,amount\n");
286	
287	        BigDecimal total = BigDecimal.ZERO;
288	
289	        for (Reservation reservation : reservations) {
290	            BigDecimal revenue = reservation.getAmountPaid();
291	            if (reservation.getRefund() != null) {
292	                revenue = revenue.subtract(reservation.getRefund());
293	            }
294	
295	            csv.append(reservation.getId()).append(",");
296	            csv.append(reservation.getRoomNumber()).append(",");
297	            csv.append(reservation.getCheckIn().format(ISO_DATE_FORMAT)).append(",");
298	            csv.append(reservation.getCheckOut().format(ISO_DATE_FORMAT)).append(",");
299	            csv.append(reservation.getStatus()).append(",");
300	            csv.append(formatDecimal(revenue)).append("\n");
301	
302	            total = total.add(revenue);
303	        }
304	
305	        csv.append("total,").append(formatDecimal(total));
306	
307	        return csv.toString();
308	    }
309	
310	    private String formatDecimal(BigDecimal value) {
311	        return value.stripTrailingZeros().toPlainString();
312	    }
313	}
314	package br.com.marealta.service;
315	
316	import br.com.marealta.exception.*;
317	import br.com.marealta.model.*;
318	import br.com.marealta.repository.ReservationRepository;
319	import br.com.marealta.repository.RoomRepository;
320	
321	import java.math.BigDecimal;
322	import java.time.LocalDate;
323	import java.time.temporal.ChronoUnit;
324	
325	public class ReservationService {
326	    private final ReservationRepository reservationRepository;
327	    private final RoomRepository roomRepository;
328	    private final PricingService pricingService;
329	    private final DocumentService documentService;
330	    private final EmailService emailService;
331	
332	    public ReservationService(
333	            ReservationRepository reservationRepository,
334	            RoomRepository roomRepository,
335	            PricingService pricingService,
336	            DocumentService documentService,
337	            EmailService emailService) {
338	        this.reservationRepository = reservationRepository;
339	        this.roomRepository = roomRepository;
340	        this.pricingService = pricingService;
341	        this.documentService = documentService;
342	        this.emailService = emailService;
343	    }
344	
345	    public Reservation createReservation(
346	            String roomNumber,
347	            String guestName,
348	            String guestEmail,
349	            GuestIdentification guestIdentification,
350	            LocalDate checkIn,
351	            LocalDate checkOut,
352	            int guests,
353	            RatePlan ratePlan) {
354	
355	        Room room = roomRepository.findByNumber(roomNumber)
356	                .orElseThrow(() -> new RoomNotFoundException(roomNumber));
357	
358	        if (guests < 1) {
359	            throw new InvalidRequestException("Number of guests must be at least 1");
360	        }
361	
362	        if (guests > room.getCapacity()) {
363	            throw new CapacityExceededException(
364	                String.format("Room %s has capacity for %d guests, but %d were requested",
365	                    roomNumber, room.getCapacity(), guests)
366	            );
367	        }
368	
369	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
370	            throw new InvalidRequestException("Check-out must be after check-in");
371	        }
372	
373	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
374	            throw new RoomUnavailableException(
375	                String.format("Room %s is not available for the selected dates", roomNumber)
376	            );
377	        }
378	
379	        Reservation reservation = new Reservation();
380	        reservation.setRoomNumber(roomNumber);
381	        reservation.setGuestName(guestName);
382	        reservation.setGuestEmail(guestEmail);
383	        reservation.setGuestIdentification(guestIdentification);
384	        reservation.setCheckIn(checkIn);
385	        reservation.setCheckOut(checkOut);
386	        reservation.setGuests(guests);
387	        reservation.setRatePlan(ratePlan);
388	
389	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
390	        reservation.setNights(nights);
391	
392	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
393	        reservation.setSubtotal(subtotal);
394	
395	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
396	        reservation.setDiscount(discount);
397	
398	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
399	        reservation.setTotal(total);
400	
401	        reservation.setStatus(ReservationStatus.PENDING);
402	        reservation.setAmountPaid(BigDecimal.ZERO);
403	
404	        return reservationRepository.save(reservation);
405	    }
406	
407	    public Reservation confirmReservation(Long reservationId) {
408	        Reservation reservation = getReservation(reservationId);
409	
410	        if (reservation.getStatus() != ReservationStatus.PENDING) {
411	            throw new OperationNotAllowedException(
412	                "Only pending reservations can be confirmed"
413	            );
