177	
178	import java.math.BigDecimal;
179	import java.math.RoundingMode;
180	import java.time.LocalDate;
181	
182	public class PricingService {
183	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
184	
185	    public BigDecimal calculateNightPrice(Room room, LocalDate date) {
186	        BigDecimal basePrice = room.getNightlyRate();
187	        if (isHighSeason(date)) {
188	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
189	        }
190	        return basePrice.setScale(2, RoundingMode.HALF_EVEN);
191	    }
192	
193	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
194	        BigDecimal subtotal = BigDecimal.ZERO;
195	        LocalDate current = checkIn;
196	
197	        while (current.isBefore(checkOut)) {
198	            BigDecimal nightPrice = calculateNightPrice(room, current);
199	            subtotal = subtotal.add(nightPrice);
200	            current = current.plusDays(1);
201	        }
202	
203	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
204	    }
205	
206	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
207	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate());
208	        return discount.setScale(2, RoundingMode.HALF_EVEN);
209	    }
210	
211	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
212	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
213	    }
214	
215	    public BigDecimal calculateIss(BigDecimal total) {
216	        return total.multiply(new BigDecimal("0.05")).setScale(2, RoundingMode.HALF_EVEN);
217	    }
218	
219	    private boolean isHighSeason(LocalDate date) {
220	        int month = date.getMonthValue();
221	        int day = date.getDayOfMonth();
222	
223	        if (month == 7) {
224	            return true;
225	        }
226	
227	        if (month == 12 && day >= 15) {
228	            return true;
229	        }
230	
231	        if (month == 1 || month == 2) {
232	            return true;
233	        }
234	
235	        return false;
236	    }
237	}
