 83	public class ReservationRepository {
 84	    private final DataSource dataSource;
 85	
 86	    public ReservationRepository(DataSource dataSource) {
 87	        this.dataSource = dataSource;
 88	    }
 89	
 90	    public Reservation save(Reservation reservation) {
 91	        String sql = """
 92	            INSERT INTO reservations (
 93	                room_number, guest_name, guest_email,
 94	                guest_cpf, company_cnpj, company_name, guest_passport, guest_country,
 95	                check_in, check_out, guests, rate_plan,
 96	                nights, subtotal, discount, total,
 97	                status, amount_paid, refund
 98	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 99	            RETURNING id
100	            """;
101	
102	        try (Connection conn = dataSource.getConnection();
103	             PreparedStatement stmt = conn.prepareStatement(sql)) {
104	
105	            setReservationParameters(stmt, reservation);
106	
107	            try (ResultSet rs = stmt.executeQuery()) {
108	                if (rs.next()) {
109	                    reservation.setId(rs.getLong("id"));
110	                }
111	            }
112	
113	            return reservation;
114	        } catch (SQLException e) {
115	            throw new RuntimeException("Error saving reservation", e);
116	        }
117	    }
