119	    public Reservation update(Reservation reservation) {
120	        String sql = """
121	            UPDATE reservations SET
122	                status = ?, amount_paid = ?, refund = ?
123	            WHERE id = ?
124	            """;
125	
126	        try (Connection conn = dataSource.getConnection();
127	             PreparedStatement stmt = conn.prepareStatement(sql)) {
128	
129	            stmt.setString(1, reservation.getStatus().name());
130	            stmt.setBigDecimal(2, reservation.getAmountPaid());
131	            stmt.setBigDecimal(3, reservation.getRefund());
132	            stmt.setLong(4, reservation.getId());
