134	            stmt.executeUpdate();
135	            return reservation;
136	        } catch (SQLException e) {
137	            throw new RuntimeException("Error updating reservation", e);
138	        }
139	    }
140	
141	    public Optional<Reservation> findById(Long id) {
142	        String sql = """
143	            SELECT * FROM reservations WHERE id = ?
144	            """;
145	
146	        try (Connection conn = dataSource.getConnection();
147	             PreparedStatement stmt = conn.prepareStatement(sql)) {
148	
149	            stmt.setLong(1, id);
150	
151	            try (ResultSet rs = stmt.executeQuery()) {
152	                if (rs.next()) {
153	                    return Optional.of(mapReservation(rs));
154	                }
155	            }
156	        } catch (SQLException e) {
157	            throw new RuntimeException("Error finding reservation", e);
158	        }
159	
160	        return Optional.empty();
