163	    public List<Reservation> findConflictingReservations(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
164	        String sql = """
165	            SELECT * FROM reservations
166	            WHERE room_number = ?
167	            AND status NOT IN ('CANCELLED')
168	            AND check_in < ?
169	            AND check_out > ?
170	            """;
171	
172	        List<Reservation> reservations = new ArrayList<>();
173	
174	        try (Connection conn = dataSource.getConnection();
175	             PreparedStatement stmt = conn.prepareStatement(sql)) {
176	
177	            stmt.setString(1, roomNumber);
178	            stmt.setDate(2, Date.valueOf(checkOut));
179	            stmt.setDate(3, Date.valueOf(checkIn));
180	
181	            try (ResultSet rs = stmt.executeQuery()) {
182	                while (rs.next()) {
183	                    reservations.add(mapReservation(rs));
184	                }
185	            }
186	        } catch (SQLException e) {
187	            throw new RuntimeException("Error finding conflicting reservations", e);
188	        }
189	
190	        return reservations;
191	    }
