222	    public List<Reservation> findByMonth(int year, int month) {
223	        String sql = """
224	            SELECT * FROM reservations
225	            WHERE EXTRACT(YEAR FROM check_in) = ?
226	            AND EXTRACT(MONTH FROM check_in) = ?
227	            AND (amount_paid - COALESCE(refund, 0)) > 0
228	            ORDER BY check_in, id
229	            """;
230	
231	        List<Reservation> reservations = new ArrayList<>();
232	
233	        try (Connection conn = dataSource.getConnection();
234	             PreparedStatement stmt = conn.prepareStatement(sql)) {
235	
236	            stmt.setInt(1, year);
237	            stmt.setInt(2, month);
238	
239	            try (ResultSet rs = stmt.executeQuery()) {
240	                while (rs.next()) {
241	                    reservations.add(mapReservation(rs));
242	                }
243	            }
244	        } catch (SQLException e) {
245	            throw new RuntimeException("Error finding reservations by month", e);
246	        }
247	
248	        return reservations;
249	    }
