251	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws SQLException {
252	        stmt.setString(1, reservation.getRoomNumber());
253	        stmt.setString(2, reservation.getGuestName());
254	        stmt.setString(3, reservation.getGuestEmail());
255	
256	        GuestIdentification id = reservation.getGuestIdentification();
257	        stmt.setString(4, id instanceof GuestIdentification.IndividualGuest ig ? ig.cpf() : null);
258	        stmt.setString(5, id instanceof GuestIdentification.CorporateGuest cg ? cg.cnpj() : null);
259	        stmt.setString(6, id instanceof GuestIdentification.CorporateGuest cg ? cg.companyName() : null);
260	        stmt.setString(7, id instanceof GuestIdentification.ForeignGuest fg ? fg.passport() : null);
261	        stmt.setString(8, id instanceof GuestIdentification.ForeignGuest fg ? fg.country() : null);
262	
263	        stmt.setDate(9, Date.valueOf(reservation.getCheckIn()));
264	        stmt.setDate(10, Date.valueOf(reservation.getCheckOut()));
265	        stmt.setInt(11, reservation.getGuests());
266	        stmt.setString(12, reservation.getRatePlan().name());
267	        stmt.setInt(13, reservation.getNights());
268	        stmt.setBigDecimal(14, reservation.getSubtotal());
269	        stmt.setBigDecimal(15, reservation.getDiscount());
270	        stmt.setBigDecimal(16, reservation.getTotal());
271	        stmt.setString(17, reservation.getStatus().name());
272	        stmt.setBigDecimal(18, reservation.getAmountPaid());
273	        stmt.setBigDecimal(19, reservation.getRefund());
274	    }
275	
276	    private Reservation mapReservation(ResultSet rs) throws SQLException {
277	        Reservation reservation = new Reservation();
278	        reservation.setId(rs.getLong("id"));
279	        reservation.setRoomNumber(rs.getString("room_number"));
280	        reservation.setGuestName(rs.getString("guest_name"));
281	        reservation.setGuestEmail(rs.getString("guest_email"));
282	
283	        String cpf = rs.getString("guest_cpf");
284	        String cnpj = rs.getString("company_cnpj");
285	        String passport = rs.getString("guest_passport");
286	
287	        if (cpf != null) {
288	            reservation.setGuestIdentification(new GuestIdentification.IndividualGuest(cpf));
289	        } else if (cnpj != null) {
290	            String companyName = rs.getString("company_name");
291	            reservation.setGuestIdentification(new GuestIdentification.CorporateGuest(cnpj, companyName));
292	        } else if (passport != null) {
293	            String country = rs.getString("guest_country");
294	            reservation.setGuestIdentification(new GuestIdentification.ForeignGuest(passport, country));
295	        }
296	
297	        reservation.setCheckIn(rs.getDate("check_in").toLocalDate());
298	        reservation.setCheckOut(rs.getDate("check_out").toLocalDate());
299	        reservation.setGuests(rs.getInt("guests"));
300	        reservation.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
301	        reservation.setNights(rs.getInt("nights"));
302	        reservation.setSubtotal(rs.getBigDecimal("subtotal"));
303	        reservation.setDiscount(rs.getBigDecimal("discount"));
304	        reservation.setTotal(rs.getBigDecimal("total"));
305	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
306	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
307	
308	        BigDecimal refund = rs.getBigDecimal("refund");
309	        reservation.setRefund(refund);
310	
311	        return reservation;
312	    }
313	}
